INSERT INTO idempotency_record (
    owner_id, operation, idempotency_key, request_fingerprint, status,
    response_payload, error_message, created_at, updated_at, expire_at
)
VALUES (
    #{ownerId}, #{operation}, #{idempotencyKey}, #{requestFingerprint}, #{status},
    #{responsePayload}, #{errorMessage}, #{createdAt}, #{updatedAt}, #{expireAt}
)

mapper.select:
SELECT id, owner_id, operation, idempotency_key, request_fingerprint, status,
       response_payload, error_message, created_at, updated_at, expire_at
FROM idempotency_record
WHERE owner_id = #{ownerId}
  AND operation = #{operation}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

mapper.update:
UPDATE idempotency_record
SET status = 'SUCCESS',
    response_payload = #{responsePayload},
    error_message = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE idempotency_record
SET status = 'FAILED',
    error_message = #{errorMessage},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE idempotency_record
SET status = 'PROCESSING',
    response_payload = NULL,
    error_message = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND updated_at <= #{staleBefore}
